import boto3
import os
from datetime import datetime, timezone, timedelta


def handler(event, context):
    region = os.environ.get("REGION", "us-east-1")
    ec2 = boto3.client("ec2", region_name=region)

    delete_unattached_volumes(ec2)
    delete_old_snapshots(ec2)
    migrate_gp2_to_gp3(ec2)

    return {"statusCode": 200, "body": "EBS maintenance completed"}


def delete_unattached_volumes(ec2):
    """Delete all EBS volumes that are not attached to any instance."""
    print("--- Deleting unattached volumes ---")
    paginator = ec2.get_paginator("describe_volumes")
    for page in paginator.paginate(
        Filters=[{"Name": "status", "Values": ["available"]}]
    ):
        for volume in page["Volumes"]:
            vol_id = volume["VolumeId"]
            try:
                ec2.delete_volume(VolumeId=vol_id)
                print(f"Deleted unattached volume: {vol_id}")
            except Exception as e:
                print(f"Failed to delete volume {vol_id}: {e}")


def delete_old_snapshots(ec2):
    """Delete all EBS snapshots owned by this account that are older than 30 days."""
    print("--- Deleting snapshots older than 30 days ---")
    cutoff = datetime.now(timezone.utc) - timedelta(days=30)

    paginator = ec2.get_paginator("describe_snapshots")
    for page in paginator.paginate(OwnerIds=["self"]):
        for snapshot in page["Snapshots"]:
            snap_id = snapshot["SnapshotId"]
            start_time = snapshot["StartTime"]
            if start_time < cutoff:
                try:
                    ec2.delete_snapshot(SnapshotId=snap_id)
                    print(f"Deleted old snapshot: {snap_id} (created {start_time})")
                except Exception as e:
                    print(f"Failed to delete snapshot {snap_id}: {e}")


def migrate_gp2_to_gp3(ec2):
    """Modify all GP2 volumes to GP3."""
    print("--- Migrating GP2 volumes to GP3 ---")
    paginator = ec2.get_paginator("describe_volumes")
    for page in paginator.paginate(
        Filters=[{"Name": "volume-type", "Values": ["gp2"]}]
    ):
        for volume in page["Volumes"]:
            vol_id = volume["VolumeId"]
            try:
                ec2.modify_volume(VolumeId=vol_id, VolumeType="gp3")
                print(f"Migrated volume {vol_id} from GP2 to GP3")
            except Exception as e:
                print(f"Failed to migrate volume {vol_id}: {e}")
